COMMENT ON COLUMN AWARD.AWARD_ID IS 'the unique identifier for the award nomination';
COMMENT ON COLUMN AWARD.ORGANIZATION IS 'the name of the organization that grants the award';
COMMENT ON COLUMN AWARD."YEAR" IS 'the year of the nomination for the award';
COMMENT ON COLUMN AWARD.AWARD_CATEGORY IS 'the class of the award';
COMMENT ON COLUMN AWARD.AWARD IS 'the specific award';
COMMENT ON COLUMN AWARD.SERIES IS 'the name of the Law & Order series that has been nominated';
COMMENT ON COLUMN AWARD.EPISODE_ID IS 'the id of the episode that has been nominated';
COMMENT ON COLUMN AWARD.PERSON_ID IS 'the id of the person that has been nominated';
COMMENT ON COLUMN AWARD."ROLE" IS 'the role that has been nominated';
COMMENT ON COLUMN AWARD."RESULT" IS 'the nomination result';
ALTER TABLE AWARD MODIFY ("RESULT" ANNOTATIONS (ADD value_description 'Nominee / Winnercommonsense evidence: ''Winner'' means that the award was actually received.'));
COMMENT ON COLUMN CREDIT.EPISODE_ID IS 'the id of the episode to which the credit information pertains';
COMMENT ON COLUMN CREDIT.PERSON_ID IS 'the id of the person to which the credit information pertains';
COMMENT ON COLUMN CREDIT.CATEGORY IS 'the kind of credit being recognized';
COMMENT ON COLUMN CREDIT."ROLE" IS 'the role for which the person is being recognized';
ALTER TABLE CREDIT MODIFY ("ROLE" ANNOTATIONS (ADD value_description 'If the credit is for an actor, this is the name of the character he or she portrayed (Dan Florek plays Donald Craven). Otherwise, this is the production role (producer, sound editor).'));
COMMENT ON COLUMN CREDIT.CREDITED IS 'whether the credit was displayed in the credits at the end of the episode';
ALTER TABLE CREDIT MODIFY (CREDITED ANNOTATIONS (ADD value_description 'commonsense evidence: A person may fill a role in an episode, but not show up in the on-screen credits. In this case, the work is said to be "uncredited."'));
COMMENT ON COLUMN EPISODE.EPISODE_ID IS 'the unique identifier of the episode';
COMMENT ON COLUMN EPISODE.SERIES IS 'the name of the series';
COMMENT ON COLUMN EPISODE.SEASON IS 'a number indicating the season of the episode';
COMMENT ON COLUMN EPISODE.EPISODE IS 'the sequential number of the episode within a specific season';
COMMENT ON COLUMN EPISODE.NUMBER_IN_SERIES IS 'the overall sequence number of episode in the entire series';
COMMENT ON COLUMN EPISODE.TITLE IS 'the title of the episode';
COMMENT ON COLUMN EPISODE.SUMMARY IS 'a brief description of what happens in the episode';
COMMENT ON COLUMN EPISODE.AIR_DATE IS 'the date the episode was initially broadcast in the United States';
COMMENT ON COLUMN EPISODE.EPISODE_IMAGE IS 'a link to an image from the episode';
COMMENT ON COLUMN EPISODE.RATING IS 'the weighted average of the votes received for the episode';
ALTER TABLE EPISODE MODIFY (RATING ANNOTATIONS (ADD value_description 'commonsense evidence: The higher rating means the episode has more positive viewer comments.'));
COMMENT ON COLUMN EPISODE.VOTES IS 'the total number of rating votes for the episode';
COMMENT ON COLUMN KEYWORD.EPISODE_ID IS 'the id of the episode';
COMMENT ON COLUMN KEYWORD.KEYWORD IS 'the keyword that is relevant for the episode';
COMMENT ON COLUMN PERSON.PERSON_ID IS 'the unique identifier for the person';
COMMENT ON COLUMN PERSON."NAME" IS 'the name of the person';
COMMENT ON COLUMN PERSON.BIRTHDATE IS 'the date the person was born';
ALTER TABLE PERSON MODIFY (BIRTHDATE ANNOTATIONS (ADD value_description 'if null, it means this birthdate of the person is not available'));
COMMENT ON COLUMN PERSON.BIRTH_NAME IS 'the name parents gave to the person shortly after birth';
COMMENT ON COLUMN PERSON.BIRTH_PLACE IS 'the place where a person was born.';
ALTER TABLE PERSON MODIFY (BIRTH_PLACE ANNOTATIONS (ADD value_description 'commonsense evidence: the birth place info is integrate if birth_name, birth_place, birth_region don''t contain null valuethe full birth place = birth_country +birth_region +birth_place'));
COMMENT ON COLUMN PERSON.BIRTH_REGION IS 'the geographical area describing where a person was born that is larger than the birth place';
COMMENT ON COLUMN PERSON.BIRTH_COUNTRY IS 'the name of the country where the person was born';
ALTER TABLE PERSON MODIFY (BIRTH_COUNTRY ANNOTATIONS (ADD value_description 'commonsense evidence: can ask questions about its corresponding continent: e.g.: USA --> North America'));
COMMENT ON COLUMN PERSON.HEIGHT_METERS IS 'how tall the person is in meters';
COMMENT ON COLUMN PERSON.NICKNAME IS 'the nickname the person goes by';
COMMENT ON COLUMN VOTE.EPISODE_ID IS 'the id of the episode';
COMMENT ON COLUMN VOTE.STARS IS 'a number between 1 and 10 indicating how much the viewer enjoyed the episode';
ALTER TABLE VOTE MODIFY (STARS ANNOTATIONS (ADD value_description 'commonsense evidence: The higher the number, the more the episode was enjoyed'));
COMMENT ON COLUMN VOTE.VOTES IS 'The total number of viewers that gave the specific episode the number of stars indicated in the "stars" column';
COMMENT ON COLUMN VOTE."PERCENT" IS 'The percent of viewers that gave the specific episode the number of stars indicated in the "stars" column';